'use strict';

const fs = require('fs');
const path = require('path');
const { tickToFrameIndex, TICKS_PER_SECOND } = require('./time');

// Sources are real decoded frame sequences on disk (one PNG per source frame).
// Preview never guesses from the request's local state: it walks the COMMITTED
// timeline and maps the requested tick through clip + source fps to a real
// frame file. That guarantees what you see is what the adopted timeline decodes.
class MediaLibrary {
  constructor(mediaDir) {
    this.mediaDir = mediaDir;
  }

  sourceDir(sourceId) {
    // sourceId is generated by us, but guard path traversal anyway.
    if (!/^[A-Za-z0-9_-]+$/.test(sourceId)) throw new Error('illegal sourceId');
    return path.join(this.mediaDir, sourceId);
  }

  framePath(sourceId, frameIndex) {
    return path.join(this.sourceDir(sourceId), `f_${String(frameIndex).padStart(5, '0')}.png`);
  }

  hasFrame(sourceId, frameIndex) {
    return fs.existsSync(this.framePath(sourceId, frameIndex));
  }

  // Find the committed clip covering a timeline tick and resolve the exact
  // source frame. Returns null when the tick is in a gap / past the end.
  resolveFrame(snapshot, timelineTick) {
    const ordered = [...snapshot.clips].sort((a, b) => a.timelineIn - b.timelineIn);
    for (const clip of ordered) {
      if (timelineTick >= clip.timelineIn && timelineTick < clip.timelineOut) {
        const src = snapshot.sources.find((s) => s.id === clip.sourceId);
        const sourceTick = clip.srcIn + (timelineTick - clip.timelineIn);
        let frame = tickToFrameIndex(sourceTick, src.fpsNum, src.fpsDen);
        if (frame >= src.frameCount) frame = src.frameCount - 1;
        return {
          clipId: clip.id,
          sourceId: clip.sourceId,
          sourceTick,
          frameIndex: frame,
          framePath: this.framePath(clip.sourceId, frame),
        };
      }
    }
    return null;
  }

  // Decode every distinct output frame implied by the committed timeline,
  // in timeline order. The returned records are the machine-checkable render
  // list; two converged clients must produce byte-identical clip+frame tuples.
  renderPlan(snapshot) {
    const plan = [];
    const ordered = [...snapshot.clips].sort((a, b) => a.timelineIn - b.timelineIn);
    for (const clip of ordered) {
      const src = snapshot.sources.find((s) => s.id === clip.sourceId);
      const startFrame = tickToFrameIndex(clip.srcIn, src.fpsNum, src.fpsDen);
      const endExclusive = tickToFrameIndex(clip.srcOut, src.fpsNum, src.fpsDen);
      for (let f = startFrame; f < endExclusive; f += 1) {
        plan.push({
          clipId: clip.id,
          sourceId: clip.sourceId,
          frameIndex: f,
          framePath: this.framePath(clip.sourceId, f),
        });
      }
    }
    return plan;
  }
}

module.exports = { MediaLibrary, TICKS_PER_SECOND };
